window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"BeLncM4uDPI","speaker":"Robert Abela","role":"Prime Minister","country":"Malta","region":"Europe","url":"https://www.youtube.com/watch?v=BeLncM4uDPI","date":"20260925","title":"🇲🇹 Malta - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1613,"words":3003,"counts":{"claims":37,"promises":2,"attacks":2},"topics":[{"topic":"UN reform","share":0.2449,"seconds":395},{"topic":"Israel-Palestine","share":0.1318,"seconds":213},{"topic":"Trust erosion","share":0.1241,"seconds":200},{"topic":"Artificial Intelligence","share":0.1208,"seconds":195},{"topic":"Ukraine invasion","share":0.0879,"seconds":142},{"topic":"International cooperation","share":0.0781,"seconds":126},{"topic":"Global conflicts","share":0.0477,"seconds":77},{"topic":"Ocean resources","share":0.0436,"seconds":70},{"topic":"Climate change","share":0.0406,"seconds":66},{"topic":"Malta ocean law","share":0.0406,"seconds":65},{"topic":"Cyber attacks","share":0.0399,"seconds":64}],"timeline":[[6,70,"UN reform"],[71,148,"Trust erosion"],[149,223,"UN reform"],[225,293,"UN reform"],[294,359,"International cooperation"],[360,431,"Ukraine invasion"],[432,503,"Ukraine invasion"],[504,566,"Israel-Palestine"],[568,633,"Israel-Palestine"],[637,722,"Israel-Palestine"],[724,801,"Global conflicts"],[802,869,"Artificial Intelligence"],[870,934,"Artificial Intelligence"],[936,999,"Artificial Intelligence"],[1000,1065,"Cyber attacks"],[1066,1128,"UN reform"],[1129,1191,"UN reform"],[1193,1257,"UN reform"],[1259,1324,"Climate change"],[1325,1395,"Ocean resources"],[1396,1461,"Malta ocean law"],[1464,1525,"International cooperation"],[1526,1588,"Trust erosion"],[1589,1650,"Trust erosion"],[1659,1663,null]],"stances":{"UN reform":"Robert Abela states that the lack of trust is the greatest challenge currently facing the world.","Trust erosion":"Robert Abela distinguishes between legitimate skepticism and destructive suspicion, arguing that the latter undermines democratic societies.","International cooperation":"Robert Abela argues that increased cooperation, dialogue, and trust are essential to resolving global conflicts.","Ukraine invasion":"Robert Abela states that Malta and Europe must not accept despair regarding the conflict and reaffirms condemnation of the invasion while demanding a peace that guarantees Ukraine's sovereignty within its internationally recognized borders.","Israel-Palestine":"Robert Abela states that the Gaza peace plan offers the best path to ending the conflict and requires all parties to fully implement its objectives.","Global conflicts":"Robert Abela states that diminished trust reduces the chances of finding solutions to global conflicts and emphasizes the necessity of building trust despite the difficulty.","Artificial Intelligence":"Robert Abela states that the rapid spread, power, and speed of artificial intelligence present a monumental disruption and the most pressing challenge of our age.","Cyber attacks":"Robert Abela states that cyber attacks on critical infrastructure are constant and existential threats for Malta, requiring them to be a priority for the United Nations.","Climate change":"Robert Abela asserts that man-made climate change is the greatest threat to island nations like Malta and calls for immediate, firm action against inaction and disinformation.","Ocean resources":"Robert Abela highlights a 1967 Maltese initiative that advocated for treating ocean resources beyond national borders as the common heritage of mankind.","Malta ocean law":"Robert Abela states that Malta's historical demand for a law of the sea was motivated by the need to protect oceans from domination by powerful nations and to ensure they belong to all humanity, including future generations."},"claims":[{"t":39,"quote":"the chosen theme for this year's general assembly is restoring trust, managing transformation","topic":"UN reform","kind":"fact"},{"t":59,"quote":"Trust or more proper properly the lack thereof is the greatest challenge currently facing our world","topic":"UN reform","kind":"fact"},{"t":71,"quote":"The erosion of trust that has gripped our societies runs deep. Where once people embraced trust, now people are gripped by suspicion.","topic":"Trust erosion","kind":"fact"},{"t":109,"quote":"Skepticism, the legitimate questioning of those who hold power over people's lives is the lifeblood of a democratic society.","topic":"Trust erosion","kind":"fact"},{"t":206,"quote":"Nobody ever successfully renovated a house without the fate that however hard the work, however many setbacks faced along the way, the end result would be a real improvement on what went before.","topic":"UN reform","kind":"fact"},{"t":276,"quote":"An international order that for all its flaws and failures has seen more children escape hunger, more families live in peace, and more children grow into old age than any era before it.","topic":"UN reform","kind":"fact"},{"t":350,"quote":"in Malta, the smallest member state of the European Union. We have always been a bridge between Europe and the Middle East.","topic":"International cooperation","kind":"fact"},{"t":404,"quote":"Malta remains as adamant in our condemnation of that invasion today as we were on day one in February 2022.","topic":"Ukraine invasion","kind":"fact"},{"t":444,"quote":"They will only have such trust if the process follows a full and unconditional ceasefire and the full participation of Ukraine and its people in the subsequent peace talks.","topic":"Ukraine invasion","kind":"fact"},{"t":482,"quote":"The issue of trust is clearly also central to the very worrying situation in Gaza.","topic":"Ukraine invasion","kind":"fact"},{"t":512,"quote":"It is impossible to build that trust with a humanitarian situation as acute as that being experienced in Gaza right now.","topic":"Israel-Palestine","kind":"fact"},{"t":525,"quote":"Multa's voice remains unwaveringly with the global calls for safe, sustained, and unhindered humanitarian access throughout Gaza in accordance with international law.","topic":"Israel-Palestine","kind":"self_credit"},{"t":603,"quote":"That is the only solution.","topic":"Israel-Palestine","kind":"fact"},{"t":646,"quote":"Settlement running directly counter to the resolutions of this general assembly and designed to undermine the Palestinian territorial integrity must stop and stop So too must the violent settler attacks on Palestinian communities increasing at an alarming rate be halted.","topic":"Israel-Palestine","kind":"fact"},{"t":729,"quote":"Be it the conflict in Sudan, the ongoing violence in Myamar, or the instability across the Sahel","topic":"Global conflicts","kind":"fact"},{"t":749,"quote":"no trust equals no peace","topic":"Global conflicts","kind":"fact"},{"t":825,"quote":"The sheer spread and the sheer power, the sheer speed of artificial intelligence is mindblowing.","topic":"Artificial Intelligence","kind":"fact"},{"t":834,"quote":"It appears to be moving far too fast for anybody let alone governments to manage to keep pace.","topic":"Artificial Intelligence","kind":"fact"},{"t":880,"quote":"the currently existing rules, the traditional models of governance are in any way or manner up to grappling with the revolution that we are living through","topic":"Artificial Intelligence","kind":"fact"},{"t":928,"quote":"no state, however micro or mighty, has any chance of getting a grip if they try to go it alone","topic":"Artificial Intelligence","kind":"fact"},{"t":936,"quote":"We only stand a chance as humanity on getting a grip on technology that seeks to ape our humanity if we collectively work together.","topic":"Artificial Intelligence","kind":"fact"},{"t":972,"quote":"Malta, my country, wholeheartedly supports the implementation of the global digital compact and wider UN efforts to strengthen international digital","topic":"Artificial Intelligence","kind":"self_credit"},{"t":1000,"quote":"cyber attacks, attacks on critical infrastructure, the cutting of the underwater cables that connect us all to each other. These are not theoretical threats. They are constant and existential threats.","topic":"Cyber attacks","kind":"fact"},{"t":1018,"quote":"For a small nation like Malta, a small island in the Mediterranean that relies on our connections to the rest of the world, they are, yes, existential threats.","topic":"Cyber attacks","kind":"fact"},{"t":1091,"quote":"there must be no let up, no slowing down in the relentless relentless drive for reform of how this United Nations and its agencies does its business and delivers its services","topic":"UN reform","kind":"fact"},{"t":1106,"quote":"To take our foot off the gas would be to let down the millions who need this United Nations to do better, be better at tackling the problems that blight their lives","topic":"UN reform","kind":"fact"},{"t":1129,"quote":"If we are to have any hope of renewing the trust of the citizens we serve in global institutions and the global order, we have to show that those this institution can indeed deliver in ways that change tangibly lives for the better.","topic":"UN reform","kind":"fact"},{"t":1198,"quote":"Malta remains thoroughly committed to the implementation of the pact for the future and all of its associated actions.","topic":"UN reform","kind":"fact"},{"t":1223,"quote":"Malta solidly backs a strong and effective resident coordinator system as the key anchor of UN action at a country level.","topic":"UN reform","kind":"fact"},{"t":1280,"quote":"Just look at the weather extremes we have been experiencing in Europe particularly during these last weeks.","topic":"Climate change","kind":"fact"},{"t":1344,"quote":"I go back to 1967 when representing the then geographically smallest member state of the Europe of the Europe United Nations, a member state that had been a member of the United Nations for less than three years.","topic":"Ocean resources","kind":"fact"},{"t":1383,"quote":"Partardo Parardaux called for the world to treat the resources of the oceans beyond their own borders as the common heritage of mankind.","topic":"Ocean resources","kind":"fact"},{"t":1406,"quote":"it took 27 years before UNL came into being","topic":"Malta ocean law","kind":"number"},{"t":1442,"quote":"in 1988, right at the start of the concern about global warming, Malta proposed the United Nations General Assembly resolution that recognized climate change as a global problem requiring collective and global solutions","topic":"Malta ocean law","kind":"fact"},{"t":1477,"quote":"The phrase dare to dream has become perhaps the world's most common motivational phrase imploring us that all we have to do is have the courage to dream.","topic":"International cooperation","kind":"fact"},{"t":1562,"quote":"mutual suspicion can only lead to mutual destruction","topic":"Trust erosion","kind":"fact"},{"t":1568,"quote":"closing our minds to those who don't share our worldview limits our chances of solving the world's biggest problems","topic":"Trust erosion","kind":"fact"}],"promises":[{"t":709,"quote":"stands ready to play its part in building the capacity of both a renewed democratic Palestinian authority and the robust civil society that must underpin it.","topic":"Israel-Palestine","kind":"promise"},{"t":1311,"quote":"We must stand firm. Stand firm against the torrent of disinformation that fuels the deniers. Stand firm against the vested interests that seek to block effective action.","topic":"Climate change","kind":"promise"}],"attacks":[{"t":1313,"quote":"Stand firm against the torrent of disinformation that fuels the deniers.","topic":"Climate change","target":"Climate change deniers"},{"t":1319,"quote":"Stand firm against the vested interests that seek to block effective action.","topic":"Climate change","target":"Corporate lobbyists"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":6,"topic":"UN reform","text":"The assembly will hear an address by His Excellency Robert Aba, Prime Minister of the Republic of Malta. I request protocol to escort his excellency and invite him to address the Mr. President, distinguished delegates, dear friends, the chosen theme for this year's general assembly is restoring trust, managing transformation. I don't think that there could be a more appropriate framing for our discussions of this week. Trust or more proper properly the lack thereof is the greatest challenge currently facing our world."},{"t":71,"topic":"Trust erosion","text":"The erosion of trust that has gripped our societies runs deep. Where once people embraced trust, now people are gripped by suspicion. Suspicion of governments, suspicion of institutions, suspicion of businesses, all too often suspicion of each other. I am talking about suspicion, not skepticism. Skepticism, the legitimate questioning of those who hold power over people's lives is the lifeblood of a democratic society. Suspicion, however, the assumption that others are automatically looking out for their interests and not those of the common good is poison to any democratic No community can succeed if we blindly believe that our neighbors are out to do us down."},{"t":149,"topic":"UN reform","text":"Just as no country can succeed, if it blindly believes that its neighbors, even those it may long have considered and seen as friends, are out to get it. Which means restoring trust, rebuilding alliances, remaking friendships must be the central mission for all of us here at home and abroad. It must also be the central mission of the remaking of this United To change, you have to believe. We know we need to change how the United Nations works, how it takes decisions and how it delivers on the ground. But we can only make that change, achieve that transformation if we believe that change is possible. Nobody ever successfully renovated a house without the fate that however hard the work, however many setbacks faced along the way, the end result would be a real improvement on what went before."},{"t":225,"topic":"UN reform","text":"So we need to show faith that however hard the work, however many setbacks faced along the way, the end result of transforming this house, this home of all the nations will be a real step And as this United Nations embarks on its ninth decade of service, the need for a step change in how the international community works together, solves problems together is arguably needed more acutely now than ever That erosion of trust is leading to the corrosion of the international order. Not the improvement of the international order but the destruction of the international order. An international order that for all its flaws and failures has seen more children escape hunger, more families live in peace, and more children grow into old age than any era before it."},{"t":294,"topic":"International cooperation","text":"To destroy the international settlement without any idea of what comes next would be an act of wanting destruction that would rightly never be forgiven or forgotten by the tens of millions whose future it would betray. let us be bold and let us say it loud and clear. Let us be utterly Now more than ever is a moment for more cooperation, not less. More dialogue, not less, more trust, not less. That is the only way that we will manage to find paths to progress on the all too many, all true, all too intractable conflicts blighting our world today. in Malta, the smallest member state of the European Union. We have always been a bridge between Europe and the Middle East."},{"t":360,"topic":"Ukraine invasion","text":"So allow me to focus on two of those conflicts on our doorstep. Firstly, Ukraine. It is all too easy and all too great a mistake for us to fall in the trap that repelling the invasion of Ukraine becomes another neverending conflict. A grinding tragedy on the corner of our continent about which we can do nothing. Malta will never accept that despair. Europe must never accept that despair. The world must never turn its head away in despair. Malta remains as adamant in our condemnation of that invasion today as we were on day one in February 2022. and Malta is equally as adamant that a just and lasting peace must guarantee Ukraine's sovereignty within its internationally recognized borders."},{"t":432,"topic":"Ukraine invasion","text":"That will only come about through a diplomatic process that the Ukrainian people can have full trust in. They will only have such trust if the process follows a full and unconditional ceasefire and the full participation of Ukraine and its people in the subsequent peace talks. The Ukrainian people will never have trust in any search for a settlement which involves their government being frog margared to the table, one arm tied behind its back whilst the guns still blaze. The issue of trust is clearly also central to the very worrying situation in Gaza. The people of of Israel need to have trust that Hamas will be disarmed and that they will play no future role in the governance or security structures of Gaza."},{"t":504,"topic":"Israel-Palestine","text":"But the people of Gaza need to have trust that there is a path to a just peace. It is impossible to build that trust with a humanitarian situation as acute as that being experienced in Gaza right now. Multa's voice remains unwaveringly with the global calls for safe, sustained, and unhindered humanitarian access throughout Gaza in accordance with international law. We firmly believe that the Gaza peace plan provides the best path towards ending the conflict and advancing credible political progress. To achieve that progress, all parties and I emphasize all parties must fully respect and implement the objectives and commitments set out in the plan."},{"t":568,"topic":"Israel-Palestine","text":"And naturally no progress can be made if there is any question of the forced displacement of any of the Palestinian it is incumbent on each and every one of us in the international community to rebuild the trust needed to underpin the conditions where genuine progress can be made towards a negotiated and lasting twostate solution. That is the only solution. Nobody however is under any illusion. How out of reach unfortunately that seems at the moment. But nor is this the moment to shy away or run away from the only goal that will guarantee the people of Israel and Palestine living side by side with the and stability that they both deserve."},{"t":637,"topic":"Israel-Palestine","text":"any progress towards a long-term solution is being endangered by the situation in the West Bank. Settlement running directly counter to the resolutions of this general assembly and designed to undermine the Palestinian territorial integrity must stop and stop So too must the violent settler attacks on Palestinian communities increasing at an alarming rate be halted. They must be halted. These are all essential preconditions to a just and lasting peace as is a credible and reformed Palestinian authority that can demonstrate to citizens of both Palestine and Israel that it has the transparency, the accountability, the institutional effectiveness and above all the democratic legitimacy to be a truly effective ive partner for stands ready to play its part in building the capacity of both a renewed democratic Palestinian authority and the robust civil society that must underpin it."},{"t":724,"topic":"Global conflicts","text":"Not just in Ukraine, Gaza and Israel, but across the world. Be it the conflict in Sudan, the ongoing violence in Myamar, or the instability across the Sahel, it is evident that diminished trust means diminished chances of finding solutions. You could put it as starkly as no trust equals no peace. Of course, no matter the conflict, each with its own individual and particular circumstances, there is no easy way of building trust. But equally, there is no easy way of avoiding the need to build trust. We all know from our lives, as much as from the experiences of our own countries, just how hard it is to rebuild trust when it has evaporated. Yet we also know the consequences if we give up trying and the rewards that can come if however slowly and however tentatively we can start if it is hard enough to build trust human to human face to face."},{"t":802,"topic":"Artificial Intelligence","text":"It can be of course infinitely harder to build trust of machines of the technology shaping all our lives. Yet the challenge of how we can manage to trust that technology and the organizations behind it is rapidly becoming the most pressing challenge of our age. The sheer spread and the sheer power, the sheer speed of artificial intelligence is mindblowing. It appears to be moving far too fast for anybody let alone governments to manage to keep pace. It can seem whether from the perspective of a leader, consumer or parent to be overwhelming. There is no escaping that this is the biggest change and the biggest challenge that any of us will experience in our lifetime. So much so that we barely have the words to describe how monumental a disruption it is proving to be."},{"t":870,"topic":"Artificial Intelligence","text":"The usual phrases step change, paradigm shift just don't seem to capture the scale. And we should also be under no illusion that the currently existing rules, the traditional models of governance are in any way or manner up to grappling with the revolution that we are living through. Which is why if we stand any chance of helping to build citizens trust in these advanced technologies, we need to begin by being honest and that governments just as individuals we are still finding our way that we don't have all the answers. What we do have, what we must have is the will and determination to act and the right values to underpin those actions. And of course, it almost goes without saying that no state, however micro or mighty, has any chance of getting a grip if they try to go it alone."},{"t":936,"topic":"Artificial Intelligence","text":"We only stand a chance as humanity on getting a grip on technology that seeks to ape our humanity if we collectively work together. Acknowledging that the rules need to be set globally and they need to be stuck to even as they develop as the tech develops. If we are to stand any chance of securing public confidence that AI can enhance and not destroy humanity, we need a set of international rules that reflect international law. So Malta, my country, wholeheartedly supports the implementation of the global digital compact and wider UN efforts to strengthen international digital To fragment is to fail and that applies equally to fighting the new threats from the new frontline in global conflict and disruption."},{"t":1000,"topic":"Cyber attacks","text":"cyber attacks, attacks on critical infrastructure, the cutting of the underwater cables that connect us all to each other. These are not theoretical threats. They are constant and existential threats. For a small nation like Malta, a small island in the Mediterranean that relies on our connections to the rest of the world, they are, yes, existential threats. Tackling them must be a priority, the priority for this United Nations. We need to embrace every emerging technology that can help us fend off those threats and build our digital resilience. the guardians of our democracy, of our freedoms, are just as likely to be found coding at a keyboard as marching in uniform. Both must work in lock step together."},{"t":1066,"topic":"UN reform","text":"Security will always of course be physical, yes, but now it must also be digital. That change must then be reflected in the way we work together to achieve our different and common goals. I know that I am preaching to true believers, Mr. President and Mr. Secretary General, when I say that there must be no let up, no slowing down in the relentless relentless drive for reform of how this United Nations and its agencies does its business and delivers its services. To take our foot off the gas would be to let down the millions who need this United Nations to do better, be better at tackling the problems that blight their lives. That is why the goal of this general assembly, a United Nations that delivers for all is so important and so urgent."},{"t":1129,"topic":"UN reform","text":"If we are to have any hope of renewing the trust of the citizens we serve in global institutions and the global order, we have to show that those this institution can indeed deliver in ways that change tangibly lives for the better. We must never lose sight and never lose faith in the values that brought us together in the first place as nations united. Malta is and always of course will be a passionate advocate and promoter of and passionately committed to At the core of all we do must be the code and conscience of the founding charter of this United Nations. But the implementation of those values, the way we turn those fine words into fine actions must always be a process of constant evolution."},{"t":1193,"topic":"UN reform","text":"We can never stand still if we are to keep cooperation alive. So Malta remains thoroughly committed to the implementation of the pact for the future and all of its associated actions. Reforms must yes remain member statedriven and firmly anchored in the intergovernmental and efficiency must not come at the expense of effectiveness on the ground. Malta solidly backs a strong and effective resident coordinator system as the key anchor of UN action at a country level. And I can't reiterate often enough or restate strongly enough that the only effective antidote to the cancer of cynicism and suspicion is effective and concerted action to tackle the greatest threat to our people and our planet."},{"t":1259,"topic":"Climate change","text":"And alongside spreading conflict and the dangers of uncontrolled technology, the greatest threat to us all and especially island nations like Malta is man-made climate change. I say and I express this to all of you. Just look at the weather extremes we have been experiencing in Europe particularly during these last weeks. To do nothing, to stand by and just wash our hands of it would be a moral and practical betrayal of the citizens of the millions of citizens who put their faith in us that we won't flinch from the biggest problems and the toughest solutions and decisions needed to tackle them. So we must not stand by. We must stand firm. Stand firm against the torrent of disinformation that fuels the deniers. Stand firm against the vested interests that seek to block effective action."},{"t":1325,"topic":"Ocean resources","text":"Stand firm against the naysayers who say that because all don't choose to act, nobody should. To those cynics, I want to point out an instance that shows how hope can triumph over And I go back to 1967 when representing the then geographically smallest member state of the Europe of the Europe United Nations, a member state that had been a member of the United Nations for less than three years. Arvitardo spoke up in this general assembly. In a staring speech, Malta's permanent representative made a passionate plea to the world's common humanity. He may have been speaking on behalf of a very small nation, but he had a very ambitious vision. Partardo Parardaux called for the world to treat the resources of the oceans beyond their own borders as the common heritage of mankind."},{"t":1396,"topic":"Malta ocean law","text":"His demand for a law of the sea was precient but to achieve it took In fact, it took 27 years before UNL came into being. What motivated Malta's action then is what motivates Malta's demands now. Doing nothing meant leaving the world's oceans to the mercy of the world's biggest, strongest, and richest nations. Taking action showed that, and I quote, they belonged to all of humanity, those living and those who still had to be born. That spirit was ev was evident when in 1988, right at the start of the concern about global warming, Malta proposed the United Nations General Assembly resolution that recognized climate change as a global problem requiring collective and global solutions."},{"t":1464,"topic":"International cooperation","text":"Suspicion of collective action won't be counteracted by retreat. It will only be overcome by the strength to turn convictions into action. The phrase dare to dream has become perhaps the world's most common motivational phrase imploring us that all we have to do is have the courage to dream. And those dreams will almost automatically become reality. And yes, we should all indeed dare to dream. To inspire ourselves to turn hope into achievement. But to turn initial aspirations into sustainable attainment takes something more than just dreams. It takes trust. trust that by working together we achieve more than we could ever achieve alone."},{"t":1526,"topic":"Trust erosion","text":"It is that belief in the power of trust which underpins the values that brought me into public life. It is that belief in the power of trust even now when it can seem a commodity in all too short supply that convinces me that ultimately it trust will prevail that ultimately we as a world will find the courage to dial down the disbelief and crank up the confidence. If we don't if we don't realize that mutual suspicion can only lead to mutual destruction. If we don't realize that closing our minds to those who don't share our worldview limits our chances of solving the world's biggest problems. If we don't realize that limiting dialogue only to those who are like-minded in reality can only drive us further apart, we face a very bleak future indeed."},{"t":1589,"topic":"Trust erosion","text":"I refuse. Malta refuses to believe that such a future is any more inevitable than it is There is only one simple antidote to the destructive power of suspicion. It is one that may not as of yet have appeared on many motivational bumper stickers, but it is one that must be our loadar. So I say to my fellow leaders as much as I say to my fellow citizens of this planet, let us dare to trust, dare to realize that even those who we disagree with the most must become a part of the solution and not a prolonger of pain. Thank you very much."},{"t":1659,"topic":null,"text":"On behalf of the assembly, I wish to thank the prime minister of the Republic of Malta."}],"compare":[{"topic":"International Law & Order","share":0.2499,"mean":0.0594,"rank":6,"others":102},{"topic":"UN & its reform","share":0.2449,"mean":0.2045,"rank":70,"others":170},{"topic":"Israel–Palestine","share":0.1318,"mean":0.052,"rank":19,"others":76},{"topic":"Artificial Intelligence","share":0.1208,"mean":0.0501,"rank":28,"others":83},{"topic":"Russia-Ukraine War","share":0.0879,"mean":0.035,"rank":26,"others":44},{"topic":"Ocean Governance","share":0.0436,"mean":0.0066,"rank":14,"others":16},{"topic":"Climate Change","share":0.0406,"mean":0.0428,"rank":77,"others":77},{"topic":"Digital Governance","share":0.0399,"mean":0.0032,"rank":8,"others":7}]};
